import React from "react";

function About() {
  return (
    <section className="page">
      <h1>About</h1>
      <p>
        ChaiLog is a tiny React practice app. It has two pages, a list, and a star rating.
        Later, it will remember your cups with localStorage and maybe pull a quote from an API.
      </p>
      <p className="muted">
        Tech: React, react-router-dom. (axios/date-fns optional, add later if you care.)
      </p>
    </section>
  );
}

export default About;
